#Program 14
For each word O, try to find the best matching word (in terms of the Levenshtein Distance) in set A and return the integer Di corresponding to that word.

The algorithm should run in O(N x O.length) if possible.



```python
def levenshtein_distance(s1, s2):
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    if len(s2) == 0:
        return len(s1)

    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1 
            deletions = current_row[j] + 1 
            substitutions = previous_row[j] + (c1!= c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]


def f(N: int, A: list[tuple[str, int]], M: int, O: list[str]):
    A_map = {a[0]: a[1] for a in A}
    result_list = []

    for q in O:
        min_distance = float('inf')
        best_word = None

        for a in A:
            word = a[0]
            distance = levenshtein_distance(q, word)
            if distance < min_distance:
                min_distance = distance
                best_word = word

        result_list.append(A_map[best_word])

    return result_list

# Example usage:
N = 2
A = [("apple", 1), ("banana", 2)]
M = 2
O = ["app", "ぬか"]
print(f(N, A, M, O))
```

